{
}

Method.Source:
    /// <summary>
    /// To return type date based on relative day
    /// </summary>
    /// <param name = "relativeDays">To find relative date</param>
    /// <returns>Date based on parameter</returns>
    [QueryRangeFunction]
    public static date METDay(int relativeDays = 0)
    {
        utcdatetime  currentDateTime;

        currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone());

        return DateTimeUtil::date(DateTimeUtil::addDays(currentDateTime,relativeDays));
    }
